<?php

/* @autogenerated */
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Shared\Exception\ConstraintException;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\TrustedClientSubjectTypeVO;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\TrustedClientSubjectTypeOptions;

final class TrustedClientSubjectTypeVOUnitTest extends TestCase
{
    public function test_asignation_keep_value(): void
    {
        $value = TrustedClientSubjectTypeOptions::PUBLIC;
        $ref = TrustedClientSubjectTypeVO::from($value);
        $this->assertEquals(TrustedClientSubjectTypeOptions::PUBLIC, $ref->value());
        $other = TrustedClientSubjectTypeVO::tryFrom($ref, new ConstraintFailList());
        $this->assertSame($other, $ref);
        $more = TrustedClientSubjectTypeVO::from($ref);
        $this->assertSame($more, $ref);
    }
    public function test_asignation_invalid_type(): void
    {
        $errors = new ConstraintFailList();
        $other = TrustedClientSubjectTypeVO::tryFrom('1', $errors);
        $this->assertNull($other);
        $this->assertTrue($errors->hasErrors());
    }
    public function test_optimist_asignation_invalid_type(): void
    {
        $this->expectException(ConstraintException::class);
        $method = new ReflectionMethod(TrustedClientSubjectTypeVO::class, 'fromUnsafe');
        $method->invoke(null, [11, "bad"]);
    }
    public function test_equals(): void
    {
        $one = TrustedClientSubjectTypeVO::from(TrustedClientSubjectTypeOptions::PUBLIC);
        $same = TrustedClientSubjectTypeVO::from(TrustedClientSubjectTypeOptions::PUBLIC);
        $other = TrustedClientSubjectTypeVO::from(TrustedClientSubjectTypeOptions::PAIRWISE);
        $withEmpty = $one->equals(null);
        $withSame = $one->equals($same);
        $withOther = $one->equals($other);

        $this->assertFalse($withEmpty);
        $this->assertTrue($withSame);
        $this->assertFalse($withOther);
    }
}
